class ToolError(Exception):
    """사용자에게 그대로 보여줄 오류."""

def is_abs_path(p):
    """절대경로인가 — POSIX · 윈도우 드라이브 · UNC 를 전부 인정한다."""
    p = str(p or '').strip()
    if p.startswith('/'):
        return True
    if p.startswith('\\\\'):
        return True
    return len(p) >= 3 and p[1] == ':' and p[0].isalpha() and (p[2] in '\\/')

def norm_abs(p):
    """절대경로를 **하나의 표기**로 — ffmpeg 은 윈도우에서도 `/` 를 받는다.

    ★역슬래시를 그대로 두면 ffmpeg 필터 문자열(`subtitles=…`)에서 이스케이프로 먹힌다.
      경로를 만드는 자리를 한 곳으로 모아 여기서만 정규화한다.
    """
    return str(p or '').strip().replace('\\', '/').rstrip('/')

class ImageMetadataConflict(ValueError):
    """Contradictory user policy for aliases of one actual image source."""
