def _image_source_path(value, wd):
    import posixpath
    pass
    value = str(value).replace('\\', '/')
    return posixpath.normpath(value if volcano_path.is_abs_path(value) else f'{wd}/{value}')

def image_source_entries(images, path, imgdir, wd):
    """Yield exactly the aliases consumed for this source's metadata."""
    target = _image_source_path(path, wd)
    for key, row in images.items():
        if not isinstance(row, dict):
            continue
        explicit = row.get('path')
        if isinstance(explicit, str) and explicit:
            source = explicit
        elif str(key) and all(('0' <= c <= '9' for c in str(key))):
            slot = (str(key).lstrip('0') or '0').zfill(2)
            source = f'{imgdir}/{slot}.png'
        else:
            source = str(key)
        if _image_source_path(source, wd) == target:
            yield (key, row, source)

def image_source_metadata(images, path, imgdir, wd, *, fields=None):
    """Resolve image-slot aliases to the exact source, never to a group number."""
    result = {}
    for _, row, source in image_source_entries(images, path, imgdir, wd):
        for field, value in row.items():
            if fields is not None and field not in fields:
                continue
            if field in ('w', 'h', 'cx', 'cy', 'focus_measurement', 'focus_by_usage'):
                continue
            if field == 'path':
                value = source
                if field in result and _image_source_path(result[field], wd) == _image_source_path(path, wd):
                    continue
            if field in result and result[field] != value:
                raise ImageMetadataConflict(f'사진 {path}의 {field} 설정이 같은 파일의 다른 항목과 충돌합니다.')
            result[field] = value
    return result

def photo_text_request(cut, row, metadata, review):
    """Bind raw OCR clarification independently of the accepted subject recipe."""
    boxes = row.get('text_boxes')
    content = row.get('content')
    if not isinstance(boxes, list) or not isinstance(content, list) or len(content) != 4 or any((not _box(box, content[2:]) for box in boxes)):
        raise ValueError('photo_text_candidates_invalid')
    binding = dict(version=1, src=cut['src'], source_identity=row['source_identity'], size=row['size'], content=content, texts=boxes, context=cut.get('context'), text_engine=row.get('text_engine'), policy={k: metadata[k] for k in ('preserve_text', 'photo_review') if k in metadata}, review={k: v for k, v in review.items() if k not in ('max_request_bytes', 'max_media_bytes')})
    key = hashlib.sha256(json.dumps(binding, sort_keys=True, ensure_ascii=False, allow_nan=False).encode()).hexdigest()
    return dict(card=str(cut['card']), key=key, binding=binding)

def photo_text_receipt(receipt, request):
    """An explicit empty selection is evidence; absent/malformed IDs are not."""
    if not isinstance(receipt, dict) or receipt.get('key') != request['key']:
        return 'missing'
    if receipt.get('status') != 'accepted':
        return 'unresolved'
    ids = receipt.get('text_ids')
    if not isinstance(ids, list) or any((type(i) is not int or not 0 <= i < len(request['binding']['texts']) for i in ids)) or len(set(ids)) != len(ids) or (not isinstance(receipt.get('reason'), str)) or (not receipt['reason'].strip()):
        return 'unresolved'
    return 'accepted'

def _review_budget_can_resume(row, policy):
    """Only an explicitly raised limit releases a proven never-sent question."""
    blocked = (row or {}).get('review_budget_blocked')
    return isinstance(blocked, dict) and type(blocked.get('attempts_reserved')) is int and (blocked['attempts_reserved'] == 0) and (type(blocked.get('max_requests')) is int) and (blocked['max_requests'] > 0) and (policy.get('provider') == 'evolink') and (type(policy.get('max_requests')) is int) and (policy['max_requests'] > blocked['max_requests'])

def _review_needs_reply(request, replies):
    """A present SHA key is only input; a rejected unchanged answer stays pending."""
    import hashlib
    reply = replies.get(request.get('request_sha256'))
    if reply is None:
        return True
    rejected = request.get('reply_error') or {}
    fingerprint = rejected.get('submitted_reply_sha256')
    if not fingerprint:
        return False
    return fingerprint == hashlib.sha256(json.dumps(reply, sort_keys=True, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode()).hexdigest()

def _review_pending_response(response, requests, settings, step):
    """A pending model answer is resumable evidence, never a semantic verdict."""
    waiting = [r for r in requests if isinstance(r, dict) and _review_needs_reply(r, settings['focus_review_replies'])]
    response.update({k: settings[k] for k in ('review_policy', 'focus_review_replies')})
    response['carry'] = list(dict.fromkeys(response.get('carry', []) + ['review_policy', 'focus_review_replies']))
    if waiting and settings['review_policy']['provider'] == 'client':
        for key in ('do', 'measure', 'execution_recovery'):
            response.pop(key, None)
        response.update(status='need_input', next_step=step, focus_review_requests=waiting, message='현재 클라이언트가 실제 원본·표시 이미지를 검토하고 구조화 답을 반환할 차례입니다. EvoLink를 자동 사용하지 않습니다.', author={'for': step, 'keys': ['focus_review_replies'], 'why': '각 요청의 모든 실제 자료를 읽고 reply_schema의 ID/SHA와 prompt의 측정 번호로 답하세요. 읽지 못한 자료는 미완료로 유지하세요.'})
    return response

