def _prepare(pl, cuts, rows, metadata, wd, config, review_settings):
    """Clarify only raw OCR visible in the renderer's actual candidate viewport."""
    import hashlib
    pass
    requests = {}
    for cut in cuts:
        usage = str(cut['card'])
        row = rows[usage]
        if row.get('text_engine') == 'ppocr-server-det':
            try:
                requests[usage] = F.photo_text_request(cut, row, metadata[usage], config)
            except (ValueError, TypeError, KeyError) as exc:
                raise ToolError(f'{usage}: 글자 후보 실측을 읽을 수 없습니다 ({exc}).') from exc
    state = pl.get('photo_text_state') or {}
    if 'results' in state and (not isinstance(state['results'], dict)):
        raise ToolError('payload.photo_text_state.results 는 사용 컷별 결과 묶음이어야 합니다.')
    results = {}
    for usage, receipt in state.get('results', {}).items():
        if usage not in requests:
            continue
        if not isinstance(receipt, dict):
            results[usage] = dict(key=requests[usage]['key'], status='unchecked', code='photo_text_receipt_invalid', reason='payload.photo_text_state.results.' + usage + ' 결과 형식이 잘못되었습니다.')
        elif receipt.get('key') == requests[usage]['key']:
            results[usage] = receipt
    for usage, receipt in (pl.get('photo_text_results') or {}).items():
        if usage in requests and (not isinstance(receipt, dict)) and (F.photo_text_receipt(results.get(usage), requests[usage]) != 'accepted'):
            results[usage] = dict(key=requests[usage]['key'], status='unchecked', code='photo_text_receipt_invalid', reason='payload.photo_text_results.' + usage + ' 결과 형식이 잘못되었습니다.')
        if usage in requests and isinstance(receipt, dict) and (receipt.get('key') == requests[usage]['key']) and (F.photo_text_receipt(results.get(usage), requests[usage]) != 'accepted'):
            results[usage] = receipt
    results = {u: r for u, r in results.items() if not _review_budget_can_resume(r, review_settings['review_policy'])}
    active = {}
    blocked = {}

    def overlap(a, b):
        return min(a[0] + a[2], b[0] + b[2]) > max(a[0], b[0]) and min(a[1] + a[3], b[1] + b[3]) > max(a[1], b[1])

    def callback(usage, plan):
        request = requests[usage]
        binding = request['binding']
        origin = binding['content']
        boxes = [[origin[0] + b[0], origin[1] + b[1], b[2], b[3]] for b in binding['texts']]
        if plan.get('needs_replacement'):
            receipt = results[usage]
            blocked[usage] = dict(source=binding['src'], source_identity=binding['source_identity'], reason=plan['framing_reason'], review_reason=receipt['reason'], candidates=[dict(id='T' + str(i), box=binding['texts'][i]) for i in receipt['text_ids']])
            return []
        viewport = (plan.get('placement') or {}).get('viewport') or plan['crop']
        if not any((overlap(viewport, box) for box in boxes)):
            return []
        active[usage] = request
        receipt = results.get(usage)
        if F.photo_text_receipt(receipt, request) == 'accepted':
            return [boxes[i] for i in receipt['text_ids']]
        return []

    def finish():
        key = hashlib.sha256(json.dumps({u: r['key'] for u, r in active.items()}, sort_keys=True).encode()).hexdigest()
        unresolved = {u: results[u] for u, r in active.items() if F.photo_text_receipt(results.get(u), r) == 'unresolved' and results[u].get('status') != 'pending'}
        pending = [r for u, r in active.items() if F.photo_text_receipt(results.get(u), r) == 'missing' or (results.get(u) or {}).get('status') == 'pending']
        client_requests = [request for u in active for request in (results.get(u) or {}).get('review_requests', []) if (results.get(u) or {}).get('status') == 'pending']
        if pending and state.get('key') == key and state.get('execution_failed'):
            unresolved['_execution'] = {'code': 'photo_text_execution_failed'}
        current = dict(key=key, results=results, automatic_retry=False)
        pl['photo_text_state'] = current
        if pending or unresolved or blocked:
            stopping = bool(unresolved or (blocked and (not pending)))
            response = dict(status='need_input' if stopping else 'execute', next_step='render_plan', message='선택된 피사체와 확인된 불필요한 글자가 함께 걸립니다. 해당 소재 또는 보존 의도를 확인하세요.' if blocked and (not unresolved) else '글자 후보 확인이 완료되지 않았습니다. 원본과 진단을 확인해 해당 소재를 수정하세요.' if unresolved else '현재 화면에 들어오는 글자 검출 후보만 확인합니다. 완료된 피사체 선택은 유지합니다.', photo_text_state=current, photo_text_diagnostics={**blocked, **unresolved}, focus_measurements=rows, focus_state=pl.get('focus_state') or {}, carry=['photo_text_state', 'focus_measurements', 'focus_state', 'images', 'timing'])
            response.update(images=pl.get('images') or {}, timing=pl['timing'])
            if stopping and blocked and (not unresolved):
                author, instructions = _photo_text_repair(pl, blocked, requests, wd)
                response.update(author=author, next_step=author['for'], message=f'{len(blocked)}컷에서 제거 대상 글자와 피사체가 겹칩니다. 같은 요청을 반복하지 말고 아래 항목을 수정한 뒤 재개하세요.', then_call_with=[author['why'], *instructions])
                for field in author['keys']:
                    if field not in response and field in pl:
                        response[field] = pl[field]
                    if field in response and field not in response['carry']:
                        response['carry'].append(field)
            if not stopping:
                response.update(execution_recovery={'state': 'photo_text_state', 'key': key}, do=[dict(cmd='review_film_frames', preserved_text_review=True, cuts=pending, photo_review=config, **review_settings, out_dir=f'{wd}/probe/photo-text', **{'as': 'photo_text_results'})], measure=[{'as': 'photo_text_results', 'pick': 'photo_text_results'}])
            return _review_pending_response(response, client_requests, review_settings, 'render_plan')
        return None

    def frame_guard(frame, proposed):
        usage = frame.get('_photo_usage')
        if usage is None:
            return True
        request = requests.get(usage)
        source = frame['src']
        source = volcano_path.norm_abs(source if volcano_path.is_abs_path(source) else f'{wd}/{source}')
        if request is None or source != volcano_path.norm_abs(request['binding']['src']):
            raise ToolError('사진 프레임의 사용 컷과 원본 연결이 바뀌었습니다: ' + str(usage))
        binding = request['binding']
        origin = binding['content']
        before = frame['srcbox']

        def visible(edges, box):
            x, y, w, h = box
            x += origin[0]
            y += origin[1]
            return min(edges[2], x + w) > max(edges[0], x) and min(edges[3], y + h) > max(edges[1], y)
        return all((not visible(proposed, box) or visible(before, box) for box in binding['texts']))
    return (callback, finish, frame_guard)

class PhotoPlan:
    """Use callback while building parts, finish before packing, then frame_guard.

    `local_response` and `pending` retain dense local bindings for the coordinator;
    only finish()'s compact result may cross the MCP boundary.
    """
    def __init__(self, payload, cuts, rows, metadata, workdir, config, review_settings):
        self.callback,self._finish,self.frame_guard=_prepare(payload,cuts,rows,metadata,workdir,config,review_settings)
        self.local_response=None
        self.pending=[]
    def finish(self):
        response=self._finish()
        self.local_response=response
        self.pending=[cut for command in (response or {}).get('do',[]) for cut in command.get('cuts',[])]
        if response is None:return {'status':'complete','review_requests':[],'diagnostics':{}}
        # Source-bound diagnostic boxes are local as well. Public diagnostics keep
        # reason/code and editable metadata paths without geometric measurements.
        diagnostics={usage:{k:v for k,v in value.items() if k!='candidates'}
                     for usage,value in response.get('photo_text_diagnostics',{}).items()}
        requests=response.get('focus_review_requests',[])
        status='pending' if self.pending or requests else 'blocked'
        return dict(status=status,review_requests=requests,diagnostics=diagnostics,
                    **{k:response[k] for k in PHOTO_TEXT_GUIDANCE_KEYS if k in response})
